import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';
import { Relay } from '../clients/js/relay.mjs';

const base = process.env.ADMIN_URL;
const token = process.env.WAR_ADMIN_TOKEN;
const peers = [], errors = [], checks = [];
async function request(path, authorized = true) {
  return fetch(new URL(path, base), { headers: authorized ? { Authorization: `Bearer ${token}` } : {} });
}
async function listing(limit, after) {
  const url = new URL('/v1/channels', base);
  if (limit !== undefined) url.searchParams.set('limit', String(limit));
  if (after !== undefined) url.searchParams.set('after', after);
  const response = await request(url);
  assert.equal(response.status, 200);
  assert.match(response.headers.get('content-type'), /^application\/json/);
  const rows = await response.json();
  assert.ok(Array.isArray(rows));
  for (const row of rows) assert.deepEqual(Object.keys(row), ['name','name_base64','members','variables','variable_bytes']);
  return rows;
}
async function join(name) {
  const peer = await Relay.connect(process.env.RELAY_URL, name);
  peer.addEventListener('error', event => errors.push(String(event.detail)));
  peers.push(peer);
  return peer;
}
async function close(peer) {
  if (peer.ws.readyState === 3) return;
  const done = new Promise(resolve => peer.addEventListener('close', resolve, { once: true }));
  peer.close();
  const event = await done;
  assert.equal(event.detail.code, 1000);
}
async function metrics() {
  const response = await request('/metrics');
  assert.equal(response.status, 200);
  return Object.fromEntries((await response.text()).split('\n').filter(row => row.startsWith('war_')).map(row => row.split(' ').map((value,index) => index ? Number(value) : value)));
}
const names = [new Uint8Array(),new Uint8Array([0]),new Uint8Array([255]),new Uint8Array([251,255]),'abc','abc\0','π世界','1234567890abcdef','a','b'];
for (const name of names) await join(name);
assert.equal(await peers[0].setVariable('keep',true),true);
const full = await listing();
assert.equal(full.length,11);
for (const limit of [1,2,7,1000]) {
  let after, observed = [];
  for (;;) {
    const rows = await listing(limit,after);
    assert.ok(rows.length <= limit);
    observed.push(...rows);
    if (rows.length < limit) break;
    after = rows.at(-1).name_base64;
  }
  assert.deepEqual(observed,full);
}
assert.equal((await listing(1))[0].name_base64,'');
assert.notEqual((await listing(1,''))[0].name_base64,'');
checks.push('Complete traversals preserve every field and order for empty, binary, plus/slash, Unicode, NUL and 16-byte names, including the explicit empty cursor.');
for (const query of ['limit=0','limit=1001','limit=bad','after=','limit=1&after=YR%3D%3D','limit=1&limit=2']) {
  const path = `/v1/channels?${query}`;
  assert.equal((await request(path,false)).status,401);
  assert.equal((await request(path)).status,400);
}
checks.push('Authorization precedes cursor/limit validation; malformed and duplicate recognized parameters fail.');
const cursor = Buffer.from('a').toString('base64');
await close(peers[8]);
let current;
const retired = performance.now();
do {
  current = await listing();
  if (!current.some(row => row.name_base64 === cursor)) break;
  assert.ok(performance.now()-retired < 3000,'retirement deadline');
  await delay(10);
} while (true);
await join('\x01'); await join('c'); await join('b');
current = await listing();
const remaining = await listing(1000,cursor);
assert.deepEqual(remaining,current.filter(row => row.name_base64 > cursor));
assert.equal(remaining.find(row => row.name === 'b').members,2);
assert.ok(remaining.some(row => row.name === 'c'));
assert.ok(!remaining.some(row => row.name === '\x01'));
checks.push('The cursor channel is observed retired before reuse; later joins behind/ahead and updated membership preserve keyset boundaries.');
await Promise.all(peers.map(close));
const stopped = performance.now();
let final;
do {
  final = await metrics();
  if (['war_connections','war_sessions','war_queued_bytes','war_variable_bytes','war_read_buffer_reserved_bytes'].every(key => final[key] === 0)) break;
  assert.ok(performance.now()-stopped < 3000,'cleanup deadline');
  await delay(10);
} while (true);
assert.equal(final.war_channels,1);
for (const key of ['war_close_failures_total','war_transport_disconnects_total','war_protocol_errors_total','war_write_errors_total','war_routing_copied_bytes_total']) assert.equal(final[key],0,key);
assert.equal(final.war_joined_total,13); assert.equal(final.war_disconnected_total,13);
assert.deepEqual(errors,[]);
checks.push('All 13 peers close normally; channels, variable bytes, receive reservations and queued output retire without errors.');
const report = {passed:true,checks,final_metrics:final,node:process.version};
await writeFile(process.env.PAGING_ACCEPT_OUTPUT,JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({passed:true,checks:checks.length,normal_closes:13}));
